ed(Path(episodes_dir).glob(\"*.npz\"))\n    ep = dict(np.load(files[0]))\n    skip = {\"action\", \"discount\", \"image\", \"is_first\", \"is_terminal\", \"logprob\", \"reward\"}\n    keys = sorted(k for k in ep if k not in skip)\n    shapes = OrderedDict((k, tuple(ep[k].shape[1:])) for k in keys)\n    return keys, shapes, ep[\"action\"].shape[-1]\n\n\nclass FakeSpace:\n    def __init__(self, d):\n        self.spaces = OrderedDict((k, SimpleNamespace(shape=v)) for k, v in d.items())\n\n\ndef make_config(device, num_actions, gate_enabled, gate_max_dt=8, gate_dt_embed_dim=32):\n    return SimpleNamespace(\n        device=device, precision=32,\n        dyn_hidden=512, dyn_deter=512, dyn_stoch=32, dyn_discrete=32,\n        dyn_rec_depth=1, dyn_mean_act=\"none\", dyn_std_act=\"sigmoid2\",\n        dyn_min_std=0.1, unimix_ratio=0.01, initial=\"learned\",\n        num_actions=num_actions, units=512, act=\"SiLU\", norm=True,\n        encoder=dict(\n            mlp_keys=\".*\", cnn_keys=\"$^\", act=\"SiLU\", norm=True,\n            cnn_depth=32, kernel_size=4, minres=4,\n            mlp_layers=5, mlp_units=1024, symlog_inputs=True,\n        ),\n        decoder=dict(\n            mlp_keys=\".*\", cnn_keys=\"$^\", act=\"SiLU\", norm=True,\n            cnn_depth=32, kernel_size=4, minres=4,\n            mlp_layers=5, mlp_units=1024, cnn_sigmoid=False,\n            image_dist=\"mse\", vector_dist=\"symlog_mse\", outscale=1.0,\n        ),\n        reward_head=dict(layers=2, dist=\"symlog_disc\", loss_scale=1.0, outscale=0.0),\n        cont_head=dict(layers=2, loss_scale=1.0, outscale=1.0),\n        grad_heads=[\"decoder\", \"reward\", \"cont\"],\n        model_lr=1e-4, opt_eps=1e-8, grad_clip=1000, weight_decay=0.0, opt=\"adam\",\n        gate_enabled=gate_enabled, gate_max_dt=gate_max_dt,\n        gate_dt_embed_dim=gate_dt_embed_dim,\n        gate_hidden_units=256, gate_hidden_layers=2,\n        gate_tau_init=5.0, gate_tau_final=0.5, gate_tau_anneal_steps=200000,\n        gate_loss_weight=1.0,\n        gate_entropy_bonus_init=0.1, gate_entropy_bonus_final=0.01,\n        gate_curriculum_phase1=50000, gate_curriculum_phase2=150000,\n        discount=0.997,\n    )\n\n\ndef load_world_model(ckpt_path, obs_shapes, config):\n    wm = models.WorldModel(\n        FakeSpace(obs_shapes),\n        SimpleNamespace(shape=(config.num_actions,)),\n        0, config,\n    )\n    ckpt = torch.load(ckpt_path, map_location=config.device)\n    wm_state = {k[4:]: v for k, v in ckpt[\"agent_state_dict\"].items()\n                if k.startswith(\"_wm.\")}\n    wm.load_state_dict(wm_state, strict=True)\n    wm.eval()\n    return wm\n\n\ndef load_episodes(d):\n    return [dict(np.load(f)) for f in sorted(Path(d).glob(\"*.npz\"))]\n\n\ndef sample_transitions(episodes, n, seed):\n    rng = np.random.RandomState(seed)\n    pairs = []\n    for i, ep in enumerate(episodes):\n        T = ep[\"action\"].shape[0]\n        for t in range(T - 2):\n            pairs.append((i, t))\n    pairs = np.array(pairs)\n    actual_n = min(n, len(pairs))\n    idx = rng.choice(len(pairs), size=actual_n, replace=False)\n    idx.sort()\n    return [(int(pairs[i][0]), int(pairs[i][1])) for i in idx]\n\n\n@torch.no_grad()\ndef evaluate_model(wm, episodes, samples, device, obs_keys):\n    has_dt_emb = wm.dynamics._dt_embedding is not None\n    ep_to_ts = defaultdict(list)\n    for ep_idx, t in samples:\n        ep_to_ts[ep_idx].append(t)\n\n    dt1_obs, dt1_rew = [], []\n    dt2_obs, dt2_rew = [], []\n    dt1_pk = {k: [] for k in obs_keys}\n    dt2_pk = {k: [] for k in obs_keys}\n    n_eps = len(ep_to_ts)\n\n    for i, (ep_idx, timesteps) in enumerate(sorted(ep_to_ts.items())):\n        ep = episodes[ep_idx]\n        obs = {k: torch.tensor(ep[k], dtype=torch.float32, device=device).unsqueeze(0)\n               for k in obs_keys}\n        action = torch.tensor(ep[\"action\"], dtype=torch.float32, device=device).unsqueeze(0)\n        is_first = torch.tensor(ep[\"is_first\"], dtype=torch.float32, device=device).unsqueeze(0)\n        reward = torch.tensor(ep[\"reward\"], dtype=torch.float32, device=device).unsqueeze(0)\n\n        embed = wm.encoder(obs)\n        post, _ = wm.dynamics.observe(embed, action, is_first)\n\n        ts = torch.tensor(sorted(timesteps), dtype=torch.long)\n        N = len(ts)\n        post_batch = {k: v[0, ts] for k, v in post.items()}\n        act_t = action[0, ts]\n        act_t1 = action[0, ts + 1]\n\n        if has_dt_emb:\n            dt_one = torch.ones(N, dtype=torch.long, device=device)\n            pred1 = wm.dynamics.img_step(post_batch, act_t, dt=dt_one, sample=False)\n        else:\n            pred1 = wm.dynamics.img_step(post_batch, act_t, sample=False)\n\n        feat1 = wm.dynamics.get_feat(pred1).unsqueeze(0)\n        dec1 = wm.heads[\"decoder\"](feat1)\n        rew1 = wm.heads[\"reward\"](feat1)\n\n        for k in obs_keys:\n            tgt = obs[k][0, ts + 1].unsqueeze(0)\n            mse = ((dec1[k].mode() - tgt) ** 2).mean(dim=-1).squeeze(0).cpu().numpy()\n            dt1_pk[k].append(mse)\n\n        dt1_obs.append(np.stack([dt1_pk[k][-1] for k in obs_keys]).mean(0))\n        r1 = rew1.mode()\n        if r1.dim() == 3:\n            r1 = r1.squeeze(-1)\n        dt1_rew.append((r1.squeeze(0) - reward[0, ts + 1]).abs().cpu().numpy())\n\n        # dt=2: sequential rollout (two img_steps)\n        if has_dt_emb:\n            pred2 = wm.dynamics.img_step(pred1, act_t1, dt=dt_one, sample=False)\n        else:\n            pred2 = wm.dynamics.img_step(pred1, act_t1, sample=False)\n\n        feat2 = wm.dynamics.get_feat(pred2).unsqueeze(0)\n        dec2 = wm.heads[\"decoder\"](feat2)\n        rew2 = wm.heads[\"reward\"](feat2)\n\n        for k in obs_keys:\n            tgt = obs[k][0, ts + 2].unsqueeze(0)\n            mse = ((dec2[k].mode() - tgt) ** 2).mean(dim=-1).squeeze(0).cpu().numpy()\n            dt2_pk[k].append(mse)\n\n        dt2_obs.append(np.stack([dt2_pk[k][-1] for k in obs_keys]).mean(0))\n        r2 = rew2.mode()\n        if r2.dim() == 3:\n            r2 = r2.squeeze(-1)\n        dt2_rew.append((r2.squeeze(0) - reward[0, ts + 2]).abs().cpu().numpy())\n\n        if (i + 1) % 20 == 0 or i == n_eps - 1:\n            print(f\"    [{i+1}/{n_eps}] episodes done\")\n\n    dt1_obs_arr = np.concatenate(dt1_obs)\n    dt2_obs_arr = np.concatenate(dt2_obs)\n    dt1_rew_arr = np.concatenate(dt1_rew)\n    dt2_rew_arr = np.concatenate(dt2_rew)\n    d1pk = {k: float(np.mean(np.concatenate(v))) for k, v in dt1_pk.items()}\n    d2pk = {k: float(np.mean(np.concatenate(v))) for k, v in dt2_pk.items()}\n\n    return {\n        \"dt1\": {\n            \"obs_mse\": float(np.mean(dt1_obs_arr)),\n            \"obs_mse_std\": float(np.std(dt1_obs_arr)),\n            \"obs_mse_per_key\": d1pk,\n            \"reward_mae\": float(np.mean(dt1_rew_arr)),\n            \"reward_mae_std\": float(np.std(dt1_rew_arr)),\n        },\n        \"dt2\": {\n            \"obs_mse\": float(np.mean(dt2_obs_arr)),\n            \"obs_mse_std\": float(np.std(dt2_obs_arr)),\n            \"obs_mse_per_key\": d2pk,\n            \"reward_mae\": float(np.mean(dt2_rew_arr)),\n            \"reward_mae_std\": float(np.std(dt2_rew_arr)),\n        },\n        \"ratio\": {\n            \"obs\": float(np.mean(dt2_obs_arr)) / max(float(np.mean(dt1_obs_arr)), 1e-10),\n            \"reward\": float(np.mean(dt2_rew_arr)) / max(float(np.mean(dt1_rew_arr)), 1e-10),\n            \"per_key\": {k: d2pk[k] / max(d1pk[k], 1e-10) for k in obs_keys},\n        },\n    }\n\n\ndef main():\n    args = parse_args()\n    ckpt_dirs = [d.strip() for d in args.checkpoints.split(\",\")]\n    labels = [l.strip() for l in args.labels.split(\",\")]\n    assert len(ckpt_dirs) == len(labels), \\\n        f\"Mismatch: {len(ckpt_dirs)} checkpoints vs {len(labels)} labels\"\n\n    first_eps = Path(ckpt_dirs[0]) / \"train_eps\"\n    obs_keys, obs_shapes, num_actions = detect_obs_config(first_eps)\n    print(f\"obs_keys={obs_keys}, shapes={dict(obs_shapes)}, num_actions={num_actions}\")\n\n    all_results = OrderedDict()\n\n    for ckpt_dir, label in zip(ckpt_dirs, labels):\n        ckpt_path = Path(ckpt_dir) / \"latest.pt\"\n        eps_dir = Path(ckpt_dir) / \"train_eps\"\n\n        if not ckpt_path.exists():\n            print(f\"SKIP {label}: no checkpoint at {ckpt_path}\")\n            all_results[label] = {\"error\": \"checkpoint not found\",\n                                  \"checkpoint_path\": str(ckpt_path)}\n            continue\n\n        print(f\"\\n=== {label} ===\")\n        mcfg = LABEL_CONFIGS.get(label, LABEL_CONFIGS[\"trained_dt_emb\"])\n        config = make_config(args.device, num_actions, **mcfg)\n\n        try:\n            wm = load_world_model(ckpt_path, obs_shapes, config)\n            episodes = load_episodes(eps_dir)\n            samples = sample_transitions(episodes, args.n_samples, args.seed)\n            print(f\"  {len(episodes)} eps, {len(samples)} samples, \"\n                  f\"dt_emb={wm.dynamics._dt_embedding is not None}\")\n\n            res = evaluate_model(wm, episodes, samples, args.device, obs_keys)\n            res[\"exp_id\"] = Path(ckpt_dir).name\n            res[\"checkpoint_path\"] = str(ckpt_path)\n            res[\"checkpoint_size\"] = ckpt_path.stat().st_size\n            res[\"n_episodes\"] = len(episodes)\n            res[\"has_dt_embedding\"] = wm.dynamics._dt_embedding is not None\n            all_results[label] = res\n\n            print(f\"  dt1: obs_mse={res['dt1']['obs_mse']:.6f}  \"\n                  f\"reward_mae={res['dt1']['reward_mae']:.4f}\")\n            print(f\"  dt2: obs_mse={res['dt2']['obs_mse']:.6f}  \"\n                  f\"reward_mae={res['dt2']['reward_mae']:.4f}\")\n            print(f\"  ratio: obs={res['ratio']['obs']:.2f}x  \"\n                  f\"reward={res['ratio']['reward']:.2f}x\")\n            del wm\n        except Exception as e:\n            import traceback\n            traceback.print_exc()\n            all_results[label